import type { Arc } from '../types';
import { arc, battle, beat } from './arc-helpers';

/** East Blue: Romance Dawn through Loguetown. */
export const eastBlueArcs: Arc[] = [
arc({ id: 'romance-dawn', name: 'Romance Dawn', sagaId: 'east-blue', chapters: [1, 7], premise: 'A borrowed hat, an impossible promise, and the first person willing to follow.', locationIds: ['foosha-village', 'shells-town'], characterIds: ['luffy', 'zoro'], overview: [
  'Luffy’s adventure begins with an argument about what strength looks like. In Foosha Village, Shanks laughs off a bandit’s insult, then risks his life when that bandit threatens a child. Luffy initially mistakes restraint for cowardice. The rescue, and the arm Shanks loses while making it, turn an abstract fascination with pirates into a personal promise. Luffy will become a great pirate and return the straw hat entrusted to him.',
  'Ten years later, he sets out with a rubber body, very little preparation, and absolute confidence in his destination. The first recruits and rivals do not gather because he presents a convincing plan. They respond to his willingness to say what he wants and act against the people controlling their lives. Coby wants the Marines; Zoro wants the summit of swordsmanship. Luffy treats both ambitions as real before either man is in a position to pursue them.',
], beats: [
  beat('a-hat-and-a-promise', 'The promise at the shoreline', '1', [
    'Foosha Village is a quiet harbor that has grown used to the Red Hair Pirates drinking in Makino’s bar. Seven-year-old Luffy wants to sail with them so badly that he drives a knife under his own eye to prove his nerve. Shanks refuses him anyway, and Luffy, sulking at the counter, eats a strange fruit from a chest without knowing what it is. His body turns to rubber, and the sea is closed to him forever.',
    'When the mountain bandit Higuma pours drink over Shanks and mocks him, the captain laughs and cleans up the mess. Luffy is furious at what he reads as cowardice. He picks his own fight with Higuma days later and is dragged to the shore to be drowned. Shanks arrives with his crew, disperses the bandits without raising his voice, and swims after the boy when a sea king takes Higuma. The sea king takes his arm as well.',
    'Shanks tells Luffy that an arm is a small price for a friend. When the crew finally leaves, he sets his straw hat on the boy’s head and asks for it back once Luffy has become a great pirate. The gift is not a coronation. It is a debt Luffy chooses to carry, and the promise gives shape to everything he does afterward.',
  ]),
  beat('setting-sail', 'A boat too small for the sea', '1–2', [
    'Ten years pass. Luffy, now seventeen, rows out of Foosha Village in a dinghy with a barrel of supplies and no map, while the villagers watch from the harbor. The Lord of the Coast, the sea king that took Shanks’s arm, surfaces to swallow him. Luffy knocks it back with a single stretched punch, a small demonstration that his body has become something the sea must reckon with.',
    'His voyage lasts barely a day before a whirlpool swallows the boat. He survives by climbing into the barrel and letting the current carry him, which is how he arrives, asleep and packaged, on the deck of Alvida’s ship as her crew hauls the barrel aboard for what they assume is wine.',
  ]),
  beat('cobys-choice', 'Coby chooses his own course', '2', [
    'Coby has spent two years scrubbing Alvida’s decks after boarding the wrong boat, and terror has reduced his life to a set of obedient answers. He tells Luffy that he once dreamed of joining the Marines, then apologizes for saying so. Luffy does not offer comfort. He tells Coby plainly that dying for a dream is better than living without one and lets the boy hear his own excuses out loud.',
    'Alvida demands to know who the most beautiful woman on the sea is, the answer her crew recites daily. Coby, shaking, tells her the truth. Luffy flattens her with one punch and takes a lifeboat, with Coby beside him. The friendship begins on the understanding that Coby will one day wear the uniform that hunts Luffy, and neither of them treats that as a problem.',
  ]),
  beat('the-first-crewmate', 'A swordsman in the Marine yard', '3–5', [
    'At Shells Town, Roronoa Zoro has been tied to a post in the Marine base yard for three weeks. The town speaks of him as a monster, but the girl Rika tells another story: he cut down Helmeppo’s pet wolf to protect her, and accepted a month of punishment in return for the town’s safety. Helmeppo, son of Captain Morgan, has no intention of honoring the bargain. Luffy hears him say so.',
    'Luffy decides on the spot that Zoro will be his swordsman, though Zoro has not agreed. He climbs into the base to retrieve Zoro’s confiscated swords and finds three where he expected one. Coby, meanwhile, cuts Zoro’s ropes and is shot for it. Morgan’s Marines surround the yard as Luffy drops from the roof, swords in hand, and offers Zoro a choice between execution and joining a pirate.',
  ]),
  beat('kuinas-promise', 'Two thousand and one duels', '5', [
    'Zoro remembers the dojo where he trained as a child and the girl who beat him every time they crossed swords. Kuina, the master’s daughter, defeated him in two thousand matches with bamboo and then once more with real blades. Afterward she wept, because her father had told her that a girl could never become the world’s greatest swordsman, and she had begun to believe him.',
    'Zoro told her that her sex was no excuse for beating him, and the two promised that one of them would one day hold the title. The next morning Kuina fell on a staircase and died. Zoro asked for her sword, Wado Ichimonji, and carries it still. The dream he refuses to surrender in Morgan’s yard is hers as much as his.',
  ], 'flashback'),
  beat('the-salute', 'A punch for a friend', '7', [
    'With Morgan beaten, the Marines of Shells Town throw their caps in the air. Their relief does not extend to hospitality: they feed Luffy and Zoro at Rika’s family restaurant, then order the pirates off the island. Coby stands frozen when the officers ask whether he arrived with the outlaws, knowing the truth would end his career before it begins.',
    'Luffy solves the problem by mocking Coby’s past and punching him in front of everyone, giving the Marines a reason to declare that the two cannot be friends. Coby is permitted to enlist. As Luffy and Zoro row away, he salutes them from the dock, and the whole base salutes with him. Luffy has his first crewmate and his first ally on the other side.',
  ]),
], battles: [
  battle('alvida', 'Luffy versus Alvida', '2', 'Free Coby from a captain who rules her ship through fear.', 'Alvida swings an iron club that has cowed her crew for years. Luffy shrugs off the blow because his body stretches, and he uses the moment to let Coby shout the truth he has been swallowing.', 'One punch sends Alvida across the deck. Luffy and Coby leave in a lifeboat.', ['A barrel opens on Alvida’s deck', 'The iron club swings', 'Rubber does not bruise', 'Coby says the truth aloud', 'One stretched fist']),
  battle('morgan', 'Luffy and Zoro versus Morgan', '5–6', 'Free Zoro and break Morgan’s control over the base.', 'Luffy withstands ordinary gunfire while Zoro recovers the weapons that make his own style possible. Their cooperation is improvised, but each trusts the other to handle the immediate threat. Morgan’s axe-hand and his contempt for his own men count for nothing against two people who fight because they mean to.', 'Morgan falls; the Marines acknowledge their relief, while Luffy leaves Coby room to pursue his career.', ['Rifles level in the execution yard', 'Three swords returned', 'An axe swings at a rubber neck', 'Helmeppo held at pistol point', 'The captain hits the ground', 'Two ambitions depart together']),
], legacy: ['The hat becomes an expression of trust that Luffy later lends to people in crisis. Zoro’s commitment establishes a crew held together by individual dreams rather than erased by the captain’s.', 'Coby’s separate departure makes the sea morally larger than a simple pirates-versus-Marines conflict.'] }),

arc({ id: 'orange-town', name: 'Orange Town', sagaId: 'east-blue', chapters: [8, 22], premise: 'A thief, a clown, and a town whose smallest guardian refuses to leave.', locationIds: ['orange-town', 'island-of-rare-animals'], characterIds: ['luffy', 'zoro', 'nami'], overview: ['Nami enters the journey as someone who needs pirates and despises them. She steals from them, manipulates their quarrels, and refuses to call the arrangement with Luffy a friendship. Orange Town gives her a first reason to reconsider: his anger is directed at the destruction of other people’s precious things, even when those things have no value to him.', 'Buggy supplies an opposing version of piracy. His theatrical authority depends on humiliation, explosive force, and the idea that subordinates are disposable. His connection to Shanks also introduces a past larger than Luffy’s childhood recollection. Two men can sail on the same ship and emerge with very different ideas of what matters.'], beats: [
  beat('an-uneasy-partnership', 'Nami makes a bargain', '8–11', [
    'A giant bird carries Luffy off the boat and drops him into Orange Town, an emptied village where the pirate thief Nami is fleeing three of Buggy’s men with a stolen chart of the Grand Line. She lets Luffy take the blame, then proposes a partnership once she sees him win. Her idea of partnership is to hand him over to Buggy, tied up, as a way of joining the clown’s crew.',
    'Buggy orders Nami to fire his cannon at the caged prisoner. She cannot do it, and her hesitation nearly costs her life until Zoro arrives and cuts the captain in half. The pieces do not fall. Buggy has eaten the Chop-Chop Fruit, and a flying hand drives a knife into Zoro’s side. The three escape only because Zoro lifts the cage and runs, while Nami begins to learn that the man she has bound to a cannon is not the kind of pirate she has spent her life hating.',
  ]),
  beat('the-dogs-treasure', 'Chouchou keeps watch', '12–14', [
    'The mayor, Boodle, explains why the town is empty: the villagers fled Buggy, but a small dog named Chouchou stays outside a pet-food shop and guards it. His owner died in hospital and the dog is still waiting, treating the shop as the promise he was left. Luffy, still in his cage, seems to understand this without needing it explained.',
    'Mohji, the beast tamer, arrives on his lion Richie to collect Luffy. When Luffy refuses to be collected, Mohji burns the shop to the ground. Chouchou fights the lion and loses. Luffy breaks free of the cage, beats Mohji, and returns with the one box of food he could salvage from the fire. He sets it in front of the dog and says nothing. Nami, watching, has no rule that covers what she has just seen.',
  ]),
  beat('the-mayors-charge', 'Boodle refuses to hide', '15–16', [
    'Boodle has spent forty years building Orange Town from nothing, and the sight of the ruined shop breaks whatever patience he had left. He takes up a spear and marches on Buggy alone, ashamed that a dog and a stranger have fought for his town while he watched. Nami tries to talk him down; Luffy knocks him unconscious so he cannot get himself killed, then tells Buggy’s crew he means to beat them all.',
    'Buggy answers with a Buggy Ball aimed straight at the tavern. Luffy inflates himself like a balloon and sends the cannonball back into the pirates’ own ranks, wiping out most of Buggy’s crew in a single shot. Nami, who wanted to slip away with the chart, decides to stay a little longer.',
  ]),
  beat('a-clowns-past', 'A fruit swallowed by mistake', '19', [
    'Buggy and Shanks were apprentices together on the same ship long before either captained one. Buggy planned to sell a Devil Fruit for a fortune, ate a fake to fool his crewmates, and hid the real one in his mouth when Shanks startled him. He swallowed it, lost the treasure map he was hiding to the sea, and was rescued by Shanks, the man he blamed for both losses.',
    'The fruit that made him unkillable by blades also made him unable to swim, which ended his dream of hunting sunken treasure. His hatred of Shanks is bound up with the hat on Luffy’s head. When he recognizes it, the fight in Orange Town stops being about a chart or a town.',
  ], 'flashback'),
  beat('buggys-grudge', 'The hat is not ordinary treasure', '17–21', [
    'Cabaji, Buggy’s acrobatic chief of staff, rides a unicycle into the fight and goes for Zoro’s wound with every trick he has, then sneers at swordsmanship as a lesser art. Zoro, bleeding, refuses to let Luffy step in and finishes the duel with a single technique to prove that a swordsman he has never met is worth more than a clown who cheats.',
    'Buggy tears at Shanks’s hat with his flying knives and laughs at Luffy’s fury over something so worthless. Luffy stops fighting to win and starts fighting to answer that laugh. When Buggy tries to reassemble himself for a finishing blow, Nami has already tied up his feet, hands, and most of his body, and only a small, furious head and torso return to face a rubber fist.',
    'The kick that sends Buggy over the horizon coincides with the return of the villagers, who see three pirates standing in their broken square. Boodle covers for them as they run. Nami has decided to travel with them for the moment, on her own terms, with her own rules about what a pirate is still intact.',
  ]),
  beat('gaimons-vigil', 'A man in a box', '22', [
    'On the Island of Rare Animals the crew meets Gaimon, a former pirate who has lived inside a treasure chest for twenty years after falling into it while pursuing legendary riches on a cliff. The odd creatures of the island have become his friends and he guards them from other treasure hunters. He asks Luffy to fetch the chests on the cliff that he could never reach.',
    'Luffy climbs up and finds the chests empty. Rather than lie, he tells Gaimon the truth, and Gaimon laughs and cries at once, because the twenty years were not wasted after all: they made a life. He stays with the animals. The stop lasts a single chapter and quietly asks what treasure is for before the crew ever reaches the Grand Line.',
  ]),
], battles: [
  battle('cabaji', 'Zoro versus Cabaji', '17–18', 'Prove that a wounded swordsman is more than a clown on a unicycle.', 'Cabaji fights with fire, spinning tops, and a kick to the fresh knife wound in Zoro’s side. Zoro deliberately reopens the wound to show that tricks will not decide the duel.', 'One technique ends the duel. Zoro collapses to sleep, having refused any help.', ['A unicycle in the town square', 'Fire and spinning tops', 'A kick to a fresh wound', 'Zoro opens the wound himself', 'One stroke settles it']),
  battle('buggy', 'Luffy versus Buggy', '19–21', 'Stop Buggy’s attack on the town and protect Shanks’s hat.', 'Buggy avoids ordinary strikes by separating his body, but the separated pieces must still be managed. His grudge against Shanks turns the hat into a target. Nami’s intervention turns that limitation into an opening.', 'Luffy launches Buggy away; Nami travels onward with the group.', ['Knives fly at a straw hat', 'A hat torn', 'A body in pieces', 'Nami ties up the pieces', 'A small clown returns', 'Kicked over the horizon']),
], legacy: ['Nami’s alliance remains provisional, which makes her later departure a continuation of an unresolved conflict rather than a sudden reversal.', 'Buggy’s defeat is the beginning of a recurring relationship with Luffy, while Gaimon distinguishes treasure as money from treasure as the life built around it.'] }),

arc({ id: 'syrup-village', name: 'Syrup Village', sagaId: 'east-blue', chapters: [23, 41], premise: 'The village liar discovers a truth nobody will believe.', locationIds: ['syrup-village', 'going-merry'], characterIds: ['luffy', 'zoro', 'nami', 'usopp'], overview: ['Usopp fills Syrup Village with invented pirate attacks and visits Kaya with stories that make her isolated life less lonely. His lies are both performance and a defense against abandonment: his father went to sea, and his mother died waiting for a return he could only imagine. When a real attack approaches, his established reputation turns truth into something he cannot communicate.', 'Kuro has spent years impersonating a faithful servant so he can steal Kaya’s estate and disappear from his pirate identity. He is a planner who regards everyone around him as an expendable instrument. The Straw Hats, by contrast, accept a messy obligation to protect people they have only just met. Usopp does not need to become fearless to belong with them; he needs to decide that this time he will stand where the danger arrives.'], beats: [
  beat('a-butlers-patience', 'A murder disguised as inheritance', '23–27', [
    'The crew arrives at Syrup Village looking for a proper ship and is met by Usopp, a long-nosed teenager who announces eighty million followers and then admits to three small boys. He runs every morning through the village shouting that pirates are coming, and every morning nobody believes him. He also visits Kaya, a sick heiress confined to her mansion, and tells her stories that make her laugh.',
    'Kaya’s butler Klahadore throws the visitors out and insults Usopp’s absent father, the pirate Yasopp, as a common thief. Usopp hits him. The next day Luffy and Usopp, resting on the cliff, overhear Klahadore speaking with the hypnotist Jango: the butler is Captain Kuro of the Black Cat Pirates, who faked his own execution three years ago and has spent that time earning Kaya’s trust so that her murder can look like an inheritance.',
    'Usopp runs to warn the village and is laughed at. He runs to warn Kaya and is chased off as a liar who has finally gone too far. Standing alone at the edge of town, he decides that if the attack must be made into another lie, he will do it himself, so that his neighbors never learn how close the danger came.',
  ]),
  beat('hold-the-slope', 'The wrong shore and the right stand', '28–31', [
    'Luffy, Zoro, and Nami offer to fight beside Usopp, who cannot understand why strangers would do so and is too moved to argue. The plan is simple: there is only one path from the northern shore to the village, a steep slope, and they coat it in oil. Anyone who climbs will slide back down into swords and fists.',
    'At dawn the Black Cat Pirates land on the southern shore instead. The defenders sprint across the island, Zoro slipping on his own oil when Nami uses his head as a step. Usopp and Nami arrive first and hold the second slope alone, Usopp taking a blow to the face while shooting from a kneeling position. When Luffy and Zoro finally reach them, the crew has already been broken once.',
    'Jango hypnotizes his men into monstrous strength, but Luffy stares too intently at the pendulum and is hypnotized as well. He tears the figurehead from the Black Cat ship and flattens the pirates under it before falling asleep. The battle is half won and the two brothers guarding the ship have not yet moved.',
  ]),
  beat('cats-in-the-oil', 'The Nyaban brothers', '32–34', [
    'Sham and Buchi, the Nyaban brothers who guard Kuro’s ship, seem to be cowards until they are ordered to fight. Sham strips two of Zoro’s swords in a single pass and leaves him to duel two opponents with one blade. Nami, trying to return the missing swords, is caught and stepped on. Zoro holds the pair off through the oil and mud until he can reclaim what is his.',
    'Kuro arrives at the top of the slope with a watch in his hand and announces that his men have five minutes to finish or he will kill them all himself. He mocks the crew for fighting for people who owe them nothing. At the mansion, the servant Merry has discovered his master’s true identity and been cut down for it, and Kaya has learned the truth from his dying words.',
  ]),
  beat('kayas-stand', 'The heiress and the hypnotist', '34–36', [
    'Kaya walks to the slope in her nightgown and points a pistol at the man who has been her butler for three years. Kuro tells her exactly what her kindness has been worth to him, which is nothing, and tears her composure apart. Usopp, half blinded by his injuries, cannot stand up to help. He orders his three small followers to take Kaya into the forest.',
    'Jango pursues them with his razor-edged ring. Ninjin, Piiman, and Tamanegi hold him off with a shovel and their bodies, and Kaya offers to sign over her fortune if he spares the children. Usopp arrives in time to put a lead pellet through Jango’s face from long range, the first time the village liar has fired at a real pirate and hit.',
  ]),
  beat('the-captain-who-discards', 'A captain who discards his crew', '37–39', [
    'Kuro’s speed makes him invisible in motion, and his signature attack cuts down whatever stands in the path, including his own men. He tells Luffy that a crew exists to be used and abandoned. Luffy answers that he will never be that kind of captain and that a pirate who keeps his crew alive is not soft but strong.',
    'The fight is brief and uneven. Kuro slices Luffy’s cheek and boasts of a plan three years in the making; Luffy tears through it in minutes. When Kuro is beaten, Luffy throws him into the arms of the Black Cat Pirates and tells them to carry him away and remember who beat him. The pirates who were meant to be discarded pick up their captain and flee.',
  ]),
  beat('a-ship-and-a-farewell', 'Leaving the stories behind', '40–41', [
    'Usopp tells his three followers that the Usopp Pirates are finished. He is going to sea, and they must have their own lives rather than grow up organized around his absence. They cry and then salute. Kaya, on her feet for the first time in months, asks the Straw Hats to accept a caravel she has kept in secret, the Going Merry, with a ram’s head prow and a small galley.',
    'Usopp explains that his lies were never only lies. His mother Banchina lay dying and he told her every day that his father was coming home, until he began to shout it to the village as a habit of hope. He plans to sail alone in a small boat, and Luffy asks what he means, since he is already aboard. The crew now has a ship and a sharpshooter, and Kaya has a reason to become a doctor.',
  ]),
], battles: [
  battle('nyaban-brothers', 'Zoro versus the Nyaban brothers', '32–35', 'Hold the slope with one sword against two fighters who have taken the others.', 'Sham steals Wado Ichimonji and one of Zoro’s other swords, and Buchi’s weight makes each blow a hammer. Zoro fights uphill through his own oil with one blade until Nami returns the swords. Jango’s hypnosis makes Buchi stronger but not smarter.', 'Zoro cuts both brothers down and turns to face Kuro.', ['Two cats spring from the deck', 'Two swords stolen in one pass', 'One blade against two', 'Nami throws the swords back', 'Three swords in the mud', 'The brothers fall']),
  battle('kuro', 'Luffy versus Captain Kuro', '37–39', 'Protect Kaya and prevent Kuro from erasing every witness to his scheme.', 'Kuro’s high-speed attacks endanger his followers as casually as his enemies. Luffy tracks the consequences and meets him directly, opposing a captain who sees a crew as burdens to discard. Kuro’s plan is careful; Luffy’s answer is that the plan itself is the weakness.', 'Kuro is defeated and carried away by the Black Cat Pirates.', ['A servant’s mask falls', 'Claws move faster than sight', 'Speed without care', 'A captain stands for his crew', 'Thrown into his own men']),
], legacy: ['The Going Merry makes the crew a household, a change whose emotional consequences reach Water Seven and Enies Lobby.', 'Usopp’s courage is established as action under fear. His inventions and lies will repeatedly grow into unexpected tools for saving others.'] }),

arc({ id: 'baratie', name: 'Baratie', sagaId: 'east-blue', chapters: [42, 68], premise: 'On a restaurant at sea, hunger makes even an enemy someone worth saving.', locationIds: ['baratie', 'going-merry'], characterIds: ['luffy', 'zoro', 'nami', 'usopp', 'sanji'], overview: ['The Baratie’s cooks understand violence, but food is the principle holding their floating restaurant together. Sanji feeds the starving pirate Gin despite knowing that generosity can bring trouble. Don Krieg’s arrival proves the risk immediately: his fleet has been destroyed on the Grand Line, and he intends to seize the restaurant as a replacement ship.', 'The arc tests two dreams against the scale of the wider world. Mihawk shows Zoro how far he is from becoming the greatest swordsman, while Sanji’s memory of Zeff reveals why he cannot simply leave for the All Blue. Gratitude has become a debt he believes can only be repaid by giving up his own future. Luffy treats that logic as a misunderstanding of what a rescue is for.'], beats: [
  beat('scurvy-and-a-cannonball', 'A cook is needed', '42–44', [
    'The Going Merry picks up two bounty hunters, Johnny and Yosaku, old acquaintances of Zoro. Yosaku is collapsing from scurvy and Nami cures him with limes, which convinces the crew that a voyage without a cook is a voyage waiting to fail. Johnny knows a place: a floating restaurant shaped like a fish, the Baratie, a few days’ sail away.',
    'They arrive at the same time as a Marine ship carrying Lieutenant Fullbody. When he fires on them, Luffy deflects the cannonball with his body and sends it through the Baratie’s roof and into the owner’s quarters. Zeff, a former pirate with a peg leg, demands a year of unpaid labor as compensation. Luffy becomes the worst chore boy in the restaurant’s history.',
    'Inside, Fullbody complains about soup and gets his face pushed into the table by Sanji, the assistant head chef, who does not tolerate wasted food or insulted cooks. The restaurant runs on this violent hospitality. Luffy watches the man feed a starving prisoner minutes later and decides the Baratie has the cook he came for.',
  ]),
  beat('feed-the-hungry', 'A cook’s obligation', '44–48', [
    'Gin, a pirate held aboard Fullbody’s ship, staggers into the Baratie half dead from hunger and is thrown out for having no money. Sanji cooks for him on the back deck anyway and stands guard while he eats. Gin weeps into the rice. He warns Luffy that the Grand Line is a place of monsters and leaves with a debt he cannot repay.',
    'Days later a ruined galleon limps in with Don Krieg aboard, starving. Gin begs on his knees for a meal for his captain, and Sanji provides it over the cooks’ objections. Krieg eats, recovers, and announces that he will take the restaurant as his new ship. His fleet of fifty vessels went into the Grand Line and came out as one wreck. He needs food for a hundred men and he intends to have it.',
    'Zeff carries out a sack of a hundred meals and sets it on the deck. He knows what starvation does to a person and will not let men die of it, even men who mean to kill him. Krieg recognizes Zeff as the pirate who once returned from the Grand Line and demands his log. The cooks take up weapons that are also kitchen tools. Then the horizon splits, and the galleon behind Krieg is cut in half.',
  ]),
  beat('the-worlds-greatest', 'Zoro meets the summit', '49–52', [
    'Dracule Mihawk, the greatest swordsman in the world, has followed Krieg’s fleet out of the Grand Line for something to do and finishes the ship with a single stroke. Zoro recognizes the name and asks for a duel. Mihawk draws a knife the length of a finger and stops all three of Zoro’s swords with it, then asks what a frog at the bottom of a well hopes to accomplish.',
    'Zoro fights on because retreating would break his promise to Kuina. Mihawk, interested at last, draws his black blade and opens Zoro’s chest from shoulder to hip. Before he falls into the sea he turns to take the cut on his front, because wounds on the back are a swordsman’s shame. Mihawk tells him to grow strong and find him again.',
    'Pulled from the water, Zoro raises his sword toward the sky and swears to Luffy that he will never lose again until the day he has beaten Mihawk. Luffy accepts the promise with a grin. The moment is shadowed by news from the Merry: Nami has taken the ship and the crew’s savings and sailed away. Zoro, Usopp, Johnny, and Yosaku set off after her while Luffy stays to finish his fight.',
  ]),
  beat('iron-wall', 'Pearl and the hostage', '53–56', [
    'Krieg’s men board the Baratie and the cooks meet them with kitchen knives and iron pans. The restaurant’s fish-head prow detaches and becomes a small attack boat, which Patty and Carne steer into the fight. Pearl, a fighter armored in iron plates who has never bled in his life, is put in charge of finishing Sanji.',
    'Sanji fights with his legs alone because a cook’s hands are his living. He breaks Pearl’s guard and draws blood, and Pearl panics and sets himself and the deck on fire. Then Gin drags Zeff out with a gun to his head. He has taken the old man’s wooden leg and tells Sanji to stop fighting or watch the owner die.',
    'Sanji stops. He stands and lets Pearl’s flaming iron balls crush him, refusing to run and refusing to strike back. Luffy watches and does not understand a fighter who will die on his feet instead of winning. The reason lies nine years back on a rock in the middle of the ocean.',
  ]),
  beat('zeffs-gift', 'The debt that cannot be repaid by staying', '57–59', [
    'Sanji was a small boy on a passenger ship when Zeff, then a pirate captain called Red Leg for the way he fought, attacked it. A storm struck during the raid and swept both of them into the sea. Zeff dived after the child he was robbing. They washed onto a rock with no vegetation, no shelter, and one bag of food between them.',
    'Zeff gave Sanji the bag and kept another for himself, and told the boy to stay on his side of the rock. Sanji lasted days on the ration and starved anyway. When he crawled across to steal from Zeff’s sack, it held only treasure. The old man had kept nothing and, in the manga, cut off and eaten his own leg to survive. The anime changes the cause of the injury.',
    'They were rescued after eighty-five days. Both had spoken, half mad with hunger, of the All Blue, the legendary sea where every fish in the world can be found. Zeff built the Baratie to feed anyone who came hungry. Sanji has repaid the leg with his life ever since, and will not let anyone take the restaurant from the man who gave it.',
  ], 'flashback'),
  beat('gins-mercy', 'The man who could not kill', '60–62', [
    'Luffy ends the standoff by smashing the Baratie’s fin, the part of the restaurant that makes it a ship. If the building is a wreck, Krieg has nothing to win. Sanji is furious and Luffy tells him that dying here would not repay Zeff, it would waste what Zeff saved. Gin, disgusted with Pearl, takes over the fight himself.',
    'Gin and Sanji nearly kill each other with tonfa and kicks, and Gin stands over the man who fed him and finds he cannot land the final blow. He throws down his weapon and apologizes to his captain. Krieg answers by launching MH5, a poison gas shell, at the restaurant and at Gin along with it.',
    'Gin throws his gas mask to Sanji. Luffy throws his own to Gin. The cloud settles and, when it clears, Gin has breathed the poison and is dying slowly on the deck. Luffy tells Krieg that this will be the last fight of his life and means it.',
  ]),
  beat('soup-and-a-farewell', 'A cook is dismissed', '67–68', [
    'Krieg is beaten and refuses to accept it until Gin, barely alive, knocks his captain out and carries him away, promising to meet Luffy again on the Grand Line. The cooks fish Luffy out of the sea and Sanji, without being asked, begins to feed the survivors of Krieg’s crew. The restaurant has lost its fin and gained a chore boy who kept his word.',
    'Zeff and the cooks decide that Sanji must go. They complain about his food, pretend they never liked him, and push him toward the Merry until he understands what they are doing. Sanji kneels on the deck and thanks the old man for everything, and Zeff tells him to keep his feet dry. Luffy sails with a cook, and the Baratie floats on, a little smaller, behind them.',
  ]),
], battles: [
  battle('mihawk', 'Zoro versus Mihawk', '50–52', 'Test the dream of being the greatest against the man who already is.', 'Mihawk stops every technique with a knife the length of a finger and only draws his true blade when Zoro refuses to yield. The cut across Zoro’s chest is a lesson rather than an execution. Mihawk leaves him alive to grow.', 'Zoro loses completely, survives, and swears never to lose again.', ['A cross-shaped knife against three swords', 'A frog in a well', 'The black blade drawn', 'Zoro turns to take it on the front', 'A sword raised from the water', 'A vow the captain accepts']),
  battle('pearl-and-gin', 'Sanji versus Pearl and Gin', '54–61', 'Keep Krieg’s men off the Baratie without letting Zeff be shot.', 'Sanji cracks Pearl’s iron plates and draws first blood, then stops fighting altogether when Gin holds a gun to Zeff. He takes the punishment until Luffy breaks the restaurant’s fin and Gin takes the fight himself. Gin cannot kill the cook who fed him.', 'Gin drops his weapon and is poisoned by his own captain for it.', ['Iron plates and a burning deck', 'A gun at Zeff’s head', 'Sanji lowers his guard', 'Tonfa against a kick', 'Gin cannot finish', 'A gas shell falls']),
  battle('krieg', 'Luffy versus Don Krieg', '63–66', 'Keep Krieg from taking the Baratie and destroying the people who fed him.', 'Krieg relies on concealed weapons, armor, poison, and a claim to invincibility. Luffy persists through each layer, taking direct risks that make Sanji question whether retreat is the only rational response to danger. The great battle spear that explodes on impact is broken by fists that keep coming.', 'Krieg loses; Gin carries him away. Sanji is free to make his own departure.', ['A hundred weapons on one man', 'The exploding spear', 'Rubber fists on golden armor', 'The shattered spear', 'Wrapped in a steel net', 'A cook pulled from the sea']),
], legacy: ['Sanji adds a moral code and a practical craft to the crew. Food will remain one of the clearest ways the story distinguishes care from domination.', 'Mihawk establishes the Grand Line’s scale before the crew reaches it, and Zoro’s defeat becomes a promise rather than an endpoint.'] }),

arc({ id: 'arlong-park', name: 'Arlong Park', sagaId: 'east-blue', chapters: [69, 95], premise: 'Nami has spent years buying a freedom her captor never intended to sell.', locationIds: ['cocoyasi-village', 'arlong-park', 'going-merry'], characterIds: ['luffy', 'zoro', 'nami', 'usopp', 'sanji'], overview: ['Nami’s apparent betrayal leads the crew to the island she has been trying to save alone. Arlong rules through racial supremacy, tribute, and the useful labor of a captive navigator. Nami has spent years stealing enough money to purchase Cocoyasi Village under an agreement that gives the appearance of agency while leaving every real decision in Arlong’s hands.', 'The story pauses before the fight to explain what that bargain cost. Bell-mère, an adoptive mother with too little money to buy three lives, refused to pretend that her daughters were not hers. Nami’s service to Arlong grows from that wound and from the need to make her mother’s sacrifice protect someone. Her neighbors’ knowledge complicates the apparent isolation: they have allowed her deception because they want her to retain an escape route.'], beats: [
  beat('the-navigators-secret', 'A pirate tattoo, a hidden bargain', '69–73', [
    'Nami brings the Going Merry home to Arlong Park, a fortress with a sawshark for its crest, and is greeted as a member of the crew by fish-men who consider humans a lesser species. Zoro, Johnny, and Yosaku arrive first in pursuit and Zoro is captured. Usopp lands in Cocoyasi Village, where a girl named Nojiko and a man with a pinwheel on his hat named Genzo eye him as if he were already dead.',
    'Nami performs her role in front of the fish-men: she stabs Usopp through the hand and throws him into the water, having warned him under her breath to play dead. When Luffy and Sanji arrive she tells them to leave, calls them fools, and tries to make them hate her. Luffy lies down in the road and says he is not going anywhere, because he knows nothing and does not need to.',
  ]),
  beat('nojikos-account', 'What the village knows', '74–76', [
    'Zoro escapes Arlong Park by throwing fish-men into their own pool, and Usopp, alive, finds the others. Nojiko sits Sanji and Usopp down at the tangerine grove and tells them what Nami’s cruelty is protecting. Eight years ago Arlong made a deal: a hundred million berries and he will sell the village its freedom. Nami has been stealing from pirates ever since, alone, to reach that sum.',
    'The villagers know. They have hated her aloud and loved her in silence, so that if she ever failed she would be free to run without their expectations on her back. Nojiko will not let Luffy’s crew mistake Nami for a traitor, but she also asks them not to interfere with a plan that is almost complete. Zoro listens, and then goes to find something to cut.',
  ]),
  beat('bell-mere', 'Bell-mère’s tangerines', '77–80', [
    'Bell-mère was a Marine who found two children on a battlefield, a baby and a small girl, and carried them home to Cocoyasi Village. She left the service to raise them on a tangerine farm that never quite paid. Nami was the baby and Nojiko the girl. Nami stole to eat and to buy books on navigation, and Bell-mère, who could never afford enough, fought with her about it the night Arlong came.',
    'Arlong demanded a tribute of one hundred thousand berries per adult and fifty thousand per child. Bell-mère had exactly one hundred thousand. She could have passed her daughters off as strangers. Instead she told Arlong they were hers, paid for their lives with her own, and told the girls to live. Arlong shot her in front of them.',
    'He took Nami because she could draw sea charts as an eight-year-old and made her his cartographer, promising to sell the village back for a hundred million. She tattooed his crest on her arm and spent eight years in a room full of maps, stealing between voyages, while her neighbors pretended to despise her.',
  ], 'flashback'),
  beat('ask-for-help', 'The bargain collapses', '81–82', [
    'Captain Nezumi of the Marines, bought by Arlong, arrives at the tangerine grove with a warrant to confiscate pirate treasure and digs up the ninety-three million berries Nami has spent eight years gathering. Arlong has kept the letter of his promise and destroyed its meaning. The villagers, understanding at last that the deal was never real, take up their tools and march toward the fortress.',
    'Nami sits alone in the road and drives a knife into the tattoo on her arm, again and again, until Luffy stops her hand. He has never asked what she was hiding. She asks him for help, the sentence she has refused for eight years, and he sets his straw hat on her head, gathers Zoro, Sanji, and Usopp, and walks toward Arlong Park without another word.',
  ]),
  beat('the-gate-falls', 'Luffy at the gate', '83–84', [
    'The crew arrives to find the villagers already stopped at the gate and Arlong’s sea cow Mohmoo rising from the water to defend it. Luffy grabs the creature by the horns and swings it through the fish-men like a club. Then he punches Arlong in the face for making Nami cry, and the fight the island has waited eight years for begins.',
    'Arlong understands his enemy quickly. His men bury Luffy’s feet in concrete and throw him into the pool, where a Devil Fruit user drowns without struggling. The rest of the crew must fight three officers with their captain sinking behind them. Sanji dives to keep Luffy alive, and Zoro, still wounded from Mihawk, faces the six-armed Hachi.',
  ]),
  beat('break-the-room', 'Destroy the place that kept her', '89–93', [
    'Sanji and the villagers break Luffy free of the concrete and he bursts from the pool to face Arlong alone. Arlong is stronger, faster, and armored with teeth that regrow when broken. He tells Luffy that Nami’s talent belongs to him, that she will draw his charts for the rest of her life, and that a human cannot hope to compete.',
    'Arlong drives Luffy through the tower wall into Nami’s workroom. The walls are lined with eight years of perfect charts, and Luffy sees pen marks on the desk where a child stabbed the wood in rage. He does not fight Arlong; he destroys the room, tearing down the maps and instruments and then bringing his leg through the roof, collapsing Arlong Park with its owner inside.',
    'Standing in the rubble, Luffy shouts to Nami that she is his navigator. She weeps and the village weeps with her. The fortress that has stood over Cocoyasi for eight years is a pile of stone.',
  ]),
  beat('spin-pinwheel', 'A new tattoo and a pinwheel', '94–95', [
    'Nezumi tries to claim Arlong’s treasure and Nami beats him with her staff, then makes him return the money and pay for the village’s repairs before sending him off with a message for headquarters. Genzo, who has watched Nami grow up under Arlong, makes Luffy promise that she will always be smiling with him.',
    'The island celebrates for three days. Nami has the crest cut from her arm and replaced with a tangerine and a pinwheel, Bell-mère’s tree and Genzo’s hat. When the Merry departs she runs to the shore as if to say goodbye, then jumps aboard and throws open her coat, and the wallets of half the village fall out. Genzo spins his pinwheel and lets her go.',
  ]),
], battles: [
  battle('officers', 'Zoro versus Hachi, Usopp versus Chew', '85–87', 'Beat Arlong’s officers while Luffy drowns in the pool behind them.', 'Hachi wields six swords and thinks Zoro is a fish-man for holding out with a wound across his chest. Usopp flees Chew into the village, hates himself for it, and turns to fight with a hammer and his own weight when he realizes what running would make him.', 'Zoro cuts Hachi down; Usopp knocks Chew out and cannot believe it.', ['Six swords against three', 'Bandages soaked through', 'Usopp runs, then stops', 'A water bullet in the road', 'Hachi falls in the courtyard', 'A hammer and a shaking hand']),
  battle('kuroobi', 'Sanji versus Kuroobi', '87–89', 'Survive a fish-man karate master and keep Luffy breathing.', 'Kuroobi drags Sanji underwater where fish-man karate is ten times stronger, and Sanji nearly dies there before reaching Luffy. Back on the deck he asks Kuroobi to say his best line again and answers it with a kick to the head.', 'Kuroobi is beaten. Luffy is freed from the pool.', ['Karate in open air', 'Dragged into the pool', 'Ten times stronger underwater', 'A breath given to Luffy', 'A kick to the back of the skull']),
  battle('arlong', 'Luffy versus Arlong', '90–93', 'End Arlong’s rule and release Nami from the workroom that defined her captivity.', 'Arlong insists that Nami’s talent belongs to him. Luffy answers through the physical destruction of the building, attacking the structure of control as well as the person enforcing it. The saw-blade Kiribachi and Arlong’s regrowing teeth are answered with a leg through the roof.', 'Arlong Park falls. Nami’s village is free, and she joins without a hidden bargain.', ['Teeth that grow back', 'A saw-shaped blade', 'Through the wall into the map room', 'Pen marks in a child’s desk', 'The charts torn down', 'The tower breaks open']),
], legacy: ['Nami’s request for help becomes a defining statement of how this crew forms: belonging begins when someone no longer has to survive alone.', 'Arlong’s ideology is revisited on Fish-Man Island through Fisher Tiger, Jinbe, and Hody. The later history explains its roots without excusing the harm he chose to inflict.'] }),

arc({ id: 'loguetown', name: 'Loguetown', sagaId: 'east-blue', chapters: [96, 100], premise: 'At the place where the Pirate King died, Luffy nearly meets the same end.', locationIds: ['loguetown', 'going-merry'], characterIds: ['luffy', 'zoro', 'nami', 'usopp', 'sanji'], overview: ['Luffy’s first bounty makes his name public before he understands what recognition will attract. Loguetown, Roger’s birthplace and execution site, is the last major stop before the Grand Line. It offers supplies and practical preparation, but also a confrontation with the distance between wanting to be Pirate King and accepting the possibility of death along the way.', 'The town introduces pursuers whose objections differ from those of earlier villains. Smoker is a Marine who takes his responsibility seriously, and Tashigi believes famous swords should not remain in criminal hands. Their presence makes the crew’s outlaw status a continuing condition rather than a label reserved for especially cruel opponents. Luffy cannot solve every conflict by proving that the local authority is corrupt.'], beats: [
  beat('a-public-name', 'The first bounty travels', '96', [
    'A wanted poster with a price of thirty million berries passes from hand to hand across the East Blue. It reaches Coby at a Marine base, Kaya at her window, the Baratie’s kitchen, the tangerine grove, and finally Shanks, who reads it and calls for a party. Luffy’s small victories have been assembled by strangers into a reputation he has never seen.',
    'The poster also reaches Buggy, marooned on a small island and reunited with his crew, and Alvida, who has eaten the Slip-Slip Fruit and become sleek, beautiful, and devoted to the boy who once flattened her. The two join forces to hunt the straw hat. The Merry, meanwhile, heads for Loguetown to buy food and a proper sword before Reverse Mountain.',
  ]),
  beat('smoke-on-the-docks', 'The White Hunter', '96–97', [
    'Loguetown is where Gold Roger was born and where he was executed twenty-two years ago, and every pirate who passes through wants to see the scaffold. The town’s Marine captain, Smoker, sits on the harbor wall eating ice cream with a small girl, and when a pirate knocks her cone to the ground he makes the man eat it off the stones. He has never let a pirate leave Loguetown, and the newest poster in his pocket does not worry him.',
    'His subordinate Tashigi is a swordswoman who catalogues famous blades and believes none should be in a criminal’s hands. She is also short-sighted enough to walk into walls, and she does not recognize the man she bumps into in a sword shop as the bounty hunter Roronoa Zoro.',
  ], 'interlude'),
  beat('three-swords-in-a-shop', 'A cursed blade tests its owner', '97', [
    'Zoro has one sword left after Mihawk and one hundred thousand berries to replace two. In a small shop he finds Tashigi arguing over prices, and she identifies his Wado Ichimonji as one of the twenty-one great blades. The shopkeeper Ipponmatsu tries to swindle him until Zoro pulls Sandai Kitetsu from a barrel of bargain swords, a fine blade that has killed every owner it has had.',
    'Zoro tests the curse by tossing the sword spinning into the air and holding out his arm. It buries itself in the floor beside him without a scratch. Ipponmatsu, shaken, gives him Kitetsu for nothing and adds his family’s heirloom Yubashiri as well. Zoro leaves with three swords and a woman who will hunt him for one of them.',
  ]),
  beat('swords-and-execution', 'Preparations meet the past', '98–99', [
    'Luffy finds the execution platform in the town square and climbs it to see what Roger saw. Cabaji knocks him flat and Buggy locks his neck in a wooden stock while Alvida keeps the crowd back. Buggy raises a sword to take the head that Shanks’s hat sits on. Storm clouds gather, Zoro and Sanji fight through the crowd, and the Marines close in on the square.',
    'Luffy shouts to the crowd that he is the man who will become King of the Pirates, and then, with the blade descending, he grins and says he is going to die. Lightning strikes the scaffold and burns it to the ground, dropping him unharmed into the rubble. Smoker, watching, sees the grin Roger wore at the same spot and does not like the coincidence. Tashigi learns that the courteous swordsman from the shop is Roronoa Zoro.',
  ]),
  beat('into-the-storm', 'Five promises on a barrel', '100', [
    'The crew runs for the harbor through the rain while Tashigi corners Zoro and Smoker turns himself to smoke and pins Luffy to the stones. No punch can land on a body that is not there. Smoker has the captain’s head under his jitte when a hooded man with a tattooed face stops his hand and tells him to let the boy go. A gale rises out of nowhere and flings Luffy back toward his ship.',
    'The Straw Hats do not learn the stranger’s name. Smoker does: Monkey D. Dragon, the revolutionary, who says the world is waiting for the answer to something. Smoker requisitions a ship and follows the Merry out of the East Blue.',
    'Aboard the Merry, with the storm still blowing and Reverse Mountain ahead, the five set one foot each on a barrel and say what they are sailing for. King of the Pirates. The greatest swordsman. A map of the world. A brave warrior of the sea. The All Blue. They kick the barrel over and turn the ship toward the Grand Line.',
  ]),
], battles: [
  battle('tashigi', 'Zoro versus Tashigi', '99–100', 'Escape a Marine who wants Zoro’s swords in a museum, without killing her.', 'Tashigi attacks in the rain, calling Zoro a coward for hiding his name. Zoro parries her rapid strikes and takes her sword from her hand, but will not cut a woman who has done nothing but believe in her duty. She is humiliated by the mercy.', 'Zoro disarms Tashigi and leaves her standing in the rain.', ['A sword drawn in the rain', 'She learns his name', 'Shigure meets three blades', 'Disarmed, not cut', 'A promise to fight again']),
  battle('escape-loguetown', 'Escape from Loguetown', '99–100', 'Leave the island before execution or arrest ends the voyage.', 'Buggy’s ambush and Smoker’s smoke powers expose dangers Luffy cannot simply punch through. Alvida and Cabaji hold the square, lightning frees Luffy from the scaffold, and Smoker runs him down in the street. Weather and Dragon’s intervention create the opening for flight.', 'The Straw Hats leave East Blue with Smoker committed to following them.', ['The execution platform', 'A grin under the falling sword', 'Lightning over the square', 'Smoke pins a rubber man', 'A hooded stranger stays the hand', 'A ship in the storm']),
], legacy: ['The barrel scene provides a compact record of the original five dreams before the crew enters a much larger world.', 'Dragon’s unexplained intervention and Smoker’s pursuit leave questions that remain active long after the island disappears behind the ship.'] }),
];
